namespace moon::editor {
class BackgroundDialog final:public PixelDialog {
 const PixelFont& font_;const Skin& skin_;const Skin& icons_;std::filesystem::path directory_;PixelDropdown* choices_;PixelButton *create_,*cancel_,*close_,*folder_,*refresh_;std::vector<std::filesystem::path> files_;std::vector<timeline::Surface> tiles_;std::string error_;bool accepted_=false;int selected_=0;std::function<void(const timeline::Surface&,bool)> commit_;
 void load(){const auto previous=selected_>0&&selected_<=int(files_.size())?files_[selected_-1]:std::filesystem::path{};files_.clear();tiles_.clear();error_.clear();std::vector<std::u32string> names{U"纯色"};int failed=0;try{BackgroundPresetLibrary library(directory_);std::vector<std::filesystem::path> paths;for(const auto& e:std::filesystem::directory_iterator(directory_))if(e.is_regular_file()&&e.path().extension()==L".png")paths.push_back(e.path());std::sort(paths.begin(),paths.end());for(const auto& path:paths)try{std::ifstream file(path,std::ios::binary);std::vector<std::uint8_t> bytes((std::istreambuf_iterator<char>(file)),{});BackgroundPresetLibrary::validatePng(bytes);auto image=openRasterImage(path);auto slot=image.timeline().resolveSurface(image.cel().id);if(!slot.surface)throw std::runtime_error("Missing decoded preset");tiles_.push_back(*slot.surface);files_.push_back(path);auto stem=path.stem().u8string();names.push_back(stem=="grid"?U"网格":stem=="stripes"?U"条纹":stem=="diamond"?U"菱形":stem=="diamond-nested"?U"嵌套菱形":stem=="circles"?U"圆环":path.stem().u32string());}catch(const std::exception&){++failed;}}catch(const std::exception& e){error_=e.what();}if(failed)error_="部分背景预设读取失败（"+std::to_string(failed)+"）";selected_=0;for(std::size_t i=0;i<files_.size();++i)if(files_[i]==previous)selected_=int(i)+1;choices_->setOptions(names);choices_->setSelectedIndex(selected_);invalidate();}
public:
 BackgroundDialog(const PixelFont& f,const Skin& s,const Skin& icons,std::filesystem::path directory,std::function<void(const timeline::Surface&,bool)> commit):PixelDialog(s,"",ui::PopupWindow::ClickBehavior::CloseOnClickInOtherWindow),font_(f),skin_(s),icons_(icons),directory_(std::move(directory)),commit_(std::move(commit)){setAutoRemap(false);setWantFocus(true);choices_=new PixelDropdown(f,s);addChild(choices_);choices_->changed=[this](int i){selected_=i;invalidate();};create_=new PixelButton(f,s,U"创建背景图层",[this]{try{if(selected_==0){timeline::Surface solid;solid.width=solid.height=1;solid.pixels={backgroundPatternColor("solid",0,0)};commit_(solid,true);}else commit_(tiles_.at(selected_-1),false);accepted_=true;closeWindow(nullptr);}catch(const std::exception& e){error_=e.what();invalidate();}});cancel_=new PixelButton(f,s,U"取消",[this]{closeWindow(nullptr);});close_=new PixelButton(f,s,U"",[this]{closeWindow(nullptr);});close_->icon="close";close_->iconSkin=&icons_;close_->skinStyle="icon_button";folder_=new PixelButton(f,s,U"打开预设文件夹",[this]{const auto result=reinterpret_cast<INT_PTR>(ShellExecuteW(nullptr,L"open",directory_.c_str(),nullptr,nullptr,SW_SHOWNORMAL));if(result<=32){error_="无法打开预设文件夹";invalidate();}});folder_->icon="folderOpen";folder_->iconSkin=&icons_;folder_->bareIconWithCaption=true;refresh_=new PixelButton(f,s,U"刷新",[this]{load();});refresh_->icon="refresh";refresh_->iconSkin=&icons_;refresh_->bareIconWithCaption=true;for(auto b:{create_,cancel_,close_,folder_,refresh_})addChild(b);load();}
 gfx::Size minimumDialogSize(int)const override{return {360*uiScale,310*uiScale};}
 void onResize(ui::ResizeEvent& ev)override{setBoundsQuietly(ev.bounds());const auto r=bounds();choices_->setBounds({r.x+6*uiScale,r.y+60*uiScale,r.w-12*uiScale,20*uiScale});folder_->setBounds({r.x+6*uiScale,r.y+86*uiScale,116*uiScale,20*uiScale});refresh_->setBounds({r.x+124*uiScale,r.y+86*uiScale,50*uiScale,20*uiScale});create_->setBounds({r.x2()-102*uiScale,r.y2()-26*uiScale,96*uiScale,20*uiScale});cancel_->setBounds({r.x2()-162*uiScale,r.y2()-26*uiScale,58*uiScale,20*uiScale});layoutHeaderButton(close_);}
 void paintDialogContents(ui::PaintEvent& ev)override{auto& g=*ev.graphics();UiPaintScale scale(g);const auto r=uiLogical(clientBounds());drawDialogTitle(font_,g,r,U"新建背景图层");font_.draw(g,U"置于底层，不切换当前编辑目标。",r.x+6,r.y+27,skin_["text"]);font_.draw(g,U"背景预设",r.x+6,r.y+48,skin_["muted"]);const gfx::Rect preview(r.x+6,r.y+112,r.w-12,std::max(1,r.h-170));const auto tile=selected_==0?timeline::Surface{1,1,0,0,{},{},{backgroundPatternColor("solid",0,0)}}:tiles_.at(selected_-1);for(int y=0;y<preview.h;++y)for(int x=0;x<preview.w;++x){const auto p=tile.pixels[std::size_t(y%tile.height)*tile.width+x%tile.width];g.fillRect(gfx::rgba(p&255,(p>>8)&255,(p>>16)&255,p>>24),{preview.x+x,preview.y+y,1,1});}if(!error_.empty())font_.draw(g,unicodeText(error_),r.x+6,r.y2()-48,skin_["text"]);}
 bool onProcessMessage(ui::Message* msg)override{if(processDialogGeometry(msg))return true;if(msg->type()==ui::kKeyDownMessage&&static_cast<ui::KeyMessage*>(msg)->scancode()==ui::kKeyEsc){closeWindow(nullptr);return true;}return PixelPopupWindow::onProcessMessage(msg);}
 void smokeCreate(){create_->Click();}
};
void Editor::showBackgroundLayer(bool verify){if(!documentOpen_||homeOpen_||pending_!=Pending::None)return;BackgroundDialog popup(font_,skin_,toolIcons_,smoke_?assets_.parent_path()/"background-dialog-smoke-owned":backgroundPresetDirectory(),[this](const auto& tile,bool solid){document.createBackgroundLayer(tile,solid);});popup.setDisplay(display(),false);const auto area=bounds();const int w=std::min(area.w-12*uiScale,420*uiScale),h=std::min(area.h-12*uiScale,320*uiScale);popup.setBounds({area.center().x-w/2,area.center().y-h/2,w,h});ui::Timer timer(120,&popup);if(verify){timer.Tick.connect([&]{timer.stop();writeSmokeFrame(popup.display()->nativeSurface().get(),assets_.parent_path()/"background-dialog-smoke.bmp");popup.smokeCreate();});timer.start();}popup.openWindowInForeground();requestFocus();refresh();}
void Editor::smokeBackgroundLayers(){smoke_=true;homeOpen_=false;documentOpen_=true;pending_=Pending::None;document=Document(8,6);refresh();const auto active=document.layer().id;const auto history=document.historySize();showBackgroundLayer(true);if(document.timeline().state().layers.size()!=2||document.layer().id!=active||document.historySize()!=history+1||!document.timeline().state().layers.back().background)throw std::runtime_error("Background dialog creation changed editing focus or history");const auto background=document.timeline().state().layers.back().id;if(!menuCommands_.connected("convertLayerToBackground")||!menuCommands_.connected("convertLayerToRaster"))throw std::runtime_error("Background commands missing");document.selectLayer(background);menuCommands_.invoke("convertLayerToRaster");if(document.layer().background)throw std::runtime_error("Actual convert-to-raster command");menuCommands_.invoke("convertLayerToBackground");if(!document.layer().background)throw std::runtime_error("Actual convert-to-background command");document=Document();refresh();}
}

namespace moon::editor {
void Editor::smokeLinkedLayers(){smoke_=true;homeOpen_=false;documentOpen_=true;pending_=Pending::None;document=Document(6,1);document.beginStroke({0,0},0xff123456);document.commitStroke();const auto source=document.layer().id;refresh();const auto history=document.historyPosition();if(!menuCommands_.enabled("createLinkedLayer")||!menuCommands_.invoke("createLinkedLayer"))throw std::runtime_error("Actual linked-layer menu unavailable");const auto copy=document.layer().id;const auto frame=document.frame().id;auto surface=[&](const std::string& layer){return document.timeline().resolveSurface(document.timeline().findCel(layer,frame)->id).surface;};if(copy==source||document.historyPosition()!=history+1||surface(copy)->pixels.identity()!=surface(source)->pixels.identity())throw std::runtime_error("Actual linked layer creation");document.beginStroke({0,0},0xffabcdef);if(surface(source)->pixels[0]!=0xffabcdef)throw std::runtime_error("Linked live paint preview");document.cancelStroke();if(surface(source)->pixels[0]!=0xff123456)throw std::runtime_error("Linked paint cancel");if(!menuCommands_.enabled("convertLayerToRaster")||!menuCommands_.invoke("convertLayerToRaster")||!document.layer().linkedContentId.empty()||surface(copy)->pixels.identity()==surface(source)->pixels.identity())throw std::runtime_error("Actual linked layer raster conversion");document.undo();if(document.layer().linkedContentId.empty()||surface(copy)->pixels.identity()!=surface(source)->pixels.identity())throw std::runtime_error("Linked conversion undo");document.redo();if(!document.layer().linkedContentId.empty())throw std::runtime_error("Linked conversion redo");document=Document();refresh();}
}
